import codecs
try:
    codecs.escape_decode(bytes([92]), "ignore")
except ValueError as error:
    print(type(error).__name__, error.args, error.__context__, error.__cause__, error.__suppress_context__, error.__traceback__ is not None, flush=True)
print(codecs.escape_decode(bytes([65, 92, 120, 52, 50])), flush=True)

